        self.question = question
        self._options = []  # insertion order
        self._votes = {}    # voter -> option

    def add_option(self, option: str) -> None:
        if option not in self._options:
            self._options.append(option)

    def vote(self, voter: str, option: str) -> None:
        if voter in self._votes:
            raise ValueError(f"Voter '{voter}' has already voted.")
        if option not in self._options:
            raise ValueError(f"Option '{option}' does not exist.")
        self._votes[voter] = option

    def winner(self) -> str | None:
        if not self._options:
            return None

        counts = {opt: 0 for opt in self._options}
        for opt in self._votes.values():
            counts[opt] += 1

        best = None
        best_count = -1
        for opt in self._options:  # insertion order; later ones overwrite on tie
            if counts[opt] >= best_count:
                best_count = counts[opt]
                best = opt

        # If no votes at all, return the last added option? Alternatively None.
        # Spec says winner is option with most votes; with zero votes, all tie,
        # and last added wins.
        return best
